mapper.select:
SELECT A.FXMDMB AS fxmdmb, A.FXMDMD AS fxmdmd, IFNULL(C1.SUBJECT_NAME, D1.DETAIL_SUBJECT_NAME) AS bsubjectName , IFNULL(C2.SUBJECT_NAME, D2.DETAIL_SUBJECT_NAME) AS dsubjectName, A.BJE AS bje, A.DJE AS dje, (A.DJE-A.BJE) AS cje, A.BSL AS bsl, A.DSL AS dsl, (A.DSL-A.BSL) AS csl, A.CHECK_FLAG AS checkFlag, A.BJEO AS bjeo, A.DJEO AS djeo, (A.DJEO-A.BJEO) AS cjeo, A.BJET AS bjet, A.DJET AS djet, (A.DJET-A.BJET) AS cjet FROM SZT_INTERF_RETURN_DETAIL A INNER JOIN SZT_INTERF_VALUATION B ON A.REF_NO = B.SERIALNO INNER JOIN BOK_BOOKSET BB ON BB.ACCT_SUBJECT_ID= B.FINPROD_ID LEFT JOIN BOK_SUBJECT C1 ON A.FXMDMB = C1.SUBJECT_NO AND C1.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_SUBJECT C2 ON A.FXMDMD = C2.SUBJECT_NO AND C2.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB D1 ON A.FXMDMB = D1.DETAIL_SUBJECT_NO AND D1.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB D2 ON A.FXMDMD = D2.DETAIL_SUBJECT_NO AND D2.BOOKSET_ID = BB.BOOKSET_ID WHERE A.REF_NO = #{serialNo} AND B.INTER_TYPE = #{interType}
and A.RESULT !=#{INTER_TYPE_BALANCE}
and C1.SUBJECT_LEVEL = #{subjectLevel} and D1.DETAIL_SUBJECT_NO IS NULL
and C1.SUBJECT_NO IS NULL
